def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    # Find connected components of the rectangular 3-patterns and retain their bounds.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            points = []
            while todo:
                a, b = todo.pop()
                points.append((a, b))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    x, y = a + dr, b + dc
                    if (0 <= x < h and 0 <= y < w and grid[x][y] == 3
                            and (x, y) not in seen):
                        seen.add((x, y))
                        todo.append((x, y))
            boxes.append((min(x for x, _ in points), max(x for x, _ in points),
                          min(y for _, y in points), max(y for _, y in points)))

    # A 2 inside one of those regions marks a 3x3 patch; preserve all 2 markers.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                       for r0, r1, c0, c1 in boxes):
                for i in range(max(0, r - 1), min(h, r + 2)):
                    for j in range(max(0, c - 1), min(w, c + 2)):
                        if grid[i][j] != 2:
                            out[i][j] = 1
    return out
